package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="billable_events",uniqueConstraints=@UniqueConstraint(name="uq_billable_transfer_event",columnNames={"transfer_id","event_type"})) public class BillableEvent{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(optional=false) private TransferTransaction transfer;@ManyToOne(optional=false) private Customer customer;@Column(name="event_type",nullable=false,length=50) private String eventType;@ManyToOne(optional=false) @JoinColumn(name="pricing_plan_version_id") private PricingPlanVersion pricingPlanVersion;@Column(name="base_fee",nullable=false,precision=19,scale=4) private BigDecimal baseFee;@Column(name="tax_amount",nullable=false,precision=19,scale=4) private BigDecimal taxAmount;@Column(name="charge_amount",nullable=false,precision=19,scale=4) private BigDecimal chargeAmount;@Column(nullable=false,length=3) private String currency;@Column(nullable=false,length=20) private String status;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();if(status==null)status="PENDING";}public BigDecimal getChargeAmount(){return chargeAmount;}public void setTransfer(TransferTransaction v){transfer=v;}public void setCustomer(Customer v){customer=v;}public void setEventType(String v){eventType=v;}public void setPricingPlanVersion(PricingPlanVersion v){pricingPlanVersion=v;}public void setBaseFee(BigDecimal v){baseFee=v;}public void setTaxAmount(BigDecimal v){taxAmount=v;}public void setChargeAmount(BigDecimal v){chargeAmount=v;}public void setCurrency(String v){currency=v;}}
